// ProposalListModal.jsx
import React, { useEffect, useState } from 'react';
import { Modal, ModalHeader, ModalBody, ModalFooter, Button } from 'reactstrap';

const ProposalListModal = ({ isOpen, toggle, userId }) => {
    const [proposals, setProposals] = useState([]);

    useEffect(() => {
        if (userId) {
            fetch(`http://localhost:8080/api/proposals?userId=${userId}`)
                .then((response) => response.json())
                .then((data) => {
                    setProposals(data);
                })
                .catch((error) => console.error('Error:', error));
        }
    }, [userId]);

    return (
        <Modal isOpen={isOpen} toggle={toggle}>
            <ModalHeader toggle={toggle}>제안서 목록</ModalHeader>
            <ModalBody>
                <ul>
                    {proposals.map((proposal) => (
                        <li key={proposal.id}>{proposal.goodName}</li>
                    ))}
                </ul>
            </ModalBody>
            <ModalFooter>
                <Button color="secondary" onClick={toggle}>
                    닫기
                </Button>
            </ModalFooter>
        </Modal>
    );
};

export default ProposalListModal;
